baseflow.validate:
(nodeData) => {
  const props = nodeData.props;
  if (props.default) {
    return;
  }
  if (!props.conditions) {
    return { error: "条件不能为空" };
  }
  if (typeof props.conditions !== "string") {
    for (const groups of props.conditions.groups) {
      for (const item of groups.items) {
        if (!item.source.text || !item.target.text || !item.operator) {
          return { error: "请输入" };
        }
      }
    }
  }
}
